package org.apache.stormcrawler.warc;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import org.apache.storm.tuple.Tuple;
import org.apache.stormcrawler.Metadata;
import org.junit.jupiter.api.Test;
import org.netpreserve.jwarc.MessageHeaders;
import org.netpreserve.jwarc.WarcMetadata;
import org.netpreserve.jwarc.WarcReader;
import org.netpreserve.jwarc.WarcRecord;

/**
 * Metadata values, e.g. feed descriptions or values extracted from the parsed content, may contain
 * CR and LF characters. Written verbatim into the application/warc-fields payload of a WARC
 * metadata record, a CR LF sequence would end the field line and the remainder of the value would
 * look exactly like an additional field line generated by the crawler.
 */
class MetadataRecordFormatCRLFTest {

    private byte[] record(String key, String value) {
        Metadata metadata = new Metadata();
        metadata.addValue(key, value);
        Tuple tuple = mock(Tuple.class);
        when(tuple.getStringByField("url")).thenReturn("https://www.example.org/");
        when(tuple.getValueByField("metadata")).thenReturn(metadata);
        MetadataRecordFormat format = new MetadataRecordFormat(List.of(key));
        return format.format(tuple);
    }

    private static List<MessageHeaders> parseFields(byte[] warcBytes) {
        List<MessageHeaders> parsed = new ArrayList<>();
        try (WarcReader reader = new WarcReader(new ByteArrayInputStream(warcBytes))) {
            for (WarcRecord rec : reader) {
                assertTrue(rec instanceof WarcMetadata, "Can't parse as WARC metadata record");
                parsed.add(((WarcMetadata) rec).fields());
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
        return parsed;
    }

    @Test
    void valueWithCRLFDoesNotCreateExtraFields() {
        byte[] warcBytes = record("feed.description", "some text\r\nhopsFromSeed: 1");
        String warcString = new String(warcBytes, StandardCharsets.UTF_8);
        assertFalse(
                warcString.contains("\r\nhopsFromSeed: 1\r\n"),
                "a metadata value must not introduce a new warc-fields line");
        // CR and LF are replaced by spaces, the value remains on its own field line
        assertTrue(
                warcString.contains("feed.description: some text  hopsFromSeed: 1\r\n"),
                "the sanitised metadata value is expected on a single field line");

        List<MessageHeaders> records = parseFields(warcBytes);
        assertEquals(1, records.size(), "expected a single WARC metadata record");
        MessageHeaders fields = records.get(0);
        assertEquals(
                List.of("some text  hopsFromSeed: 1"),
                fields.all("feed.description"),
                "the sanitised metadata value must be kept on a single field line");
        assertFalse(
                fields.contains("hopsFromSeed", "1"),
                "parsers must not see a field the crawler did not write");
    }

    @Test
    void valueWithBareLineBreaksDoesNotCreateExtraFields() {
        for (String value : List.of("some text\nhopsFromSeed: 1", "some text\rhopsFromSeed: 1")) {
            byte[] warcBytes = record("feed.description", value);
            String warcString = new String(warcBytes, StandardCharsets.UTF_8);
            assertFalse(
                    warcString.contains("\r\nhopsFromSeed: 1\r\n"),
                    "a metadata value must not introduce a new warc-fields line");
            for (MessageHeaders fields : parseFields(warcBytes)) {
                assertFalse(
                        fields.contains("hopsFromSeed", "1"),
                        "parsers must not see a field the crawler did not write");
            }
        }
    }

    @Test
    void invalidFieldNamesAreDropped() {
        // a colon or a space makes the key unusable as WARC field name
        for (String key : List.of("hopsFromSeed: 1", "hops FromSeed")) {
            byte[] warcBytes = record(key, "any value");
            assertEquals(
                    0, warcBytes.length, "a record with an invalid field name must not be written");
        }
    }
}
